use super::*;
use crate::{DslValue,Number,retained_clone::RetainedCloneSource,retirement::{RetireOwned,controlled::ControlledRetirement}};
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096,"original tuple frontier exceeds4096: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn heap<T>(f:impl FnOnce()->T)->(T,(usize,usize)){crate::observe_retirement_allocations(f)}
fn source(v:DslValue)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();let g=RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),..grant(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})};RetainedCloneSource::admit_owned(v,(),g).unwrap_or_else(|_|panic!("original tuple source admission")).0}
fn drain<T:RetireOwned>(v:T){let mut r=ControlledRetirement::new(v).unwrap_or_else(|_|panic!("original tuple supports typed retirement"));for _ in 0..100000{if r.terminal_is_empty(){return;}let g=grant(r.next_demand(4096).unwrap());let(p,h)=heap(||r.step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}panic!("original tuple retirement did not settle")}
fn denials(g:RetainedCloneGrant,d:RetirementDemand)->Vec<RetainedCloneGrant>{let mut values=vec![RetainedCloneGrant{maximum_items:0,..g}];if d.copy_bytes>0{values.push(RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g});}if d.capacity_bytes>0{values.push(RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g});}if d.release_bytes>0{values.push(RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g});}if d.depth>0{values.push(RetainedCloneGrant{maximum_depth:d.depth-1,..g});}values}
struct ConstructionTurn{grant:RetainedCloneGrant,issued:bool}
impl crate::NativeDecodeConstructionRecipient for ConstructionTurn{
 fn grant(&mut self,demand:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.issued);assert!(retained_clone_grant_admits(self.grant,demand));self.issued=true;Ok(self.grant)}
 fn accept(&mut self,grant:RetainedCloneGrant,progress:RetainedCloneProgress)->Result<(),ValueError>{assert!(self.issued);assert_eq!(grant,self.grant);assert!(progress.fits(grant));Ok(())}
}
fn advance<T,R:NativeReceiver<DslValue,T>>(receiver:&mut R,original:crate::retained_clone::RetainedCloneRef<'_,DslValue>,control:&mut NativeDecodeControl<'_>,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let mut recipient=ConstructionTurn{grant,issued:false};control.with_construction_recipient(&mut recipient,|control|receiver.advance(original,control,4096,grant))}
fn original_prefixes<T:NativeReceive<DslValue>>(input:impl Fn()->DslValue,check:impl Fn(&T)){
 let mut finished=0;for cut in 0..500{let original=source(input());let foreign=source(input());let g=grant(T::receive_birth_demand());let((mut r,p),h)=heap(||T::begin_receive(g).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<24,&mut callback);let mut turns=0;
  for _ in 0..cut{if r.output_ready(){break;}let d=r.demands(original.borrow(),4096).unwrap();let g=grant(d);for denied in denials(g,d){let(p,h)=heap(||advance(&mut r,original.borrow(),&mut control,denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(original.borrow(),4096).unwrap(),d);}let(p,h)=heap(||advance(&mut r,original.borrow(),&mut control,g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));assert!(r.demands(foreign.borrow(),4096).is_err());turns+=1;}
  if r.output_ready(){let d=r.take_demand().unwrap();let g=grant(d);for denied in denials(g,d){let(v,h)=heap(||r.take(denied).unwrap());assert!(v.is_none());assert_eq!(h,(0,0));}let((v,p),h)=heap(||r.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));check(&v);drain(v);finished=turns;}
  r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){break;}let d=r.close_demands(4096).unwrap();let g=grant(d);for denied in denials(g,d){let(p,h)=heap(||r.close_step(denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.close_demands(4096).unwrap(),d);}let(p,h)=heap(||r.close_step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}assert!(r.terminal_is_empty());drain(original);drain(foreign);if finished>0{break;}}
 assert!(finished>0);eprintln!("[DEBUG] original heterogeneous tuple completed {finished} paid turns and all prefixes under4096 with exact physical receipts");
}
#[test]fn original_heterogeneous_tuple_receiving_preserves_every_paid_prefix_and_wire_kind(){
 original_prefixes::<(u32,String)>(||DslValue::Array(vec![DslValue::Number(Number::UInt(17)),DslValue::String("β".into())]),|v|assert_eq!(v,&(17,"β".into())));
 original_prefixes::<(u16,u8,u8)>(||DslValue::Array(vec![DslValue::Number(Number::UInt(2024)),DslValue::Number(Number::UInt(2)),DslValue::Number(Number::UInt(29))]),|v|assert_eq!(v,&(2024,2,29)));
 for count in [1,3]{let original=source(DslValue::Array((0..count).map(|_|DslValue::Number(Number::UInt(17))).collect()));let(mut r,_)=<(u32,String) as NativeReceive<DslValue>>::begin_receive(grant(<(u32,String) as NativeReceive<DslValue>>::receive_birth_demand())).unwrap();let mut callback=|_|true;let mut control=NativeDecodeControl::new(1<<20,&mut callback);let g=grant(r.demands(original.borrow(),4096).unwrap());advance(&mut r,original.borrow(),&mut control,g).unwrap();let g=grant(r.demands(original.borrow(),4096).unwrap());let(result,h)=heap(||advance(&mut r,original.borrow(),&mut control,g));assert!(result.is_err());assert_eq!(h,(0,0));r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){break;}let g=grant(r.close_demands(4096).unwrap());let(p,h)=heap(||r.close_step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}assert!(r.terminal_is_empty());drain(original);}
}
